"""Inputs for the `fn/SetCharacterControllerVelocity` unit (character path).

The state block is pinned at `0x1442a0bc0`; the slot table at +0x40 holds
seven variant pointers plus one null slot. Every variant is the character tag
(0), so the wrapper reaches `ApplyCharacterControllerMove`; the rigid tag is
a separate open path.

Cases: null slot, null variant, changed velocity, unchanged xyz, the record
gate, count/sentinel/generation failures, a count-0 record and an inf
velocity.
"""

from __future__ import annotations

import struct
from math import inf
from typing import List

from emu_oracle import ArgSpec

STATE_BASE = 0x00007ff7c8fc0bc0
STATE_LEN = 0x1000
STATE_HEX = ""
CASES = [(0, [1.0, 2.0, 3.0, 4.0]), (140702205611064, [1.0, 2.0, 3.0, 4.0]), (140702205611008, [1.0, 2.0, 3.0, 4.0]), (140702205611008, [1.0, 2.0, 3.0, 4.0]), (140702205611016, [5.0, 6.0, 7.0, 8.0]), (140702205611024, [1.0, 2.0, 3.0, 4.0]), (140702205611032, [1.0, 2.0, 3.0, 4.0]), (140702205611040, [1.0, 2.0, 3.0, 4.0]), (140702205611048, [1.0, 2.0, 3.0, 4.0]), (140702205611056, [1.0, 2.0, 3.0, 4.0]), (140702205611008, [inf, 0.0, 0.0, 0.0]), (140702205611064, [1.0, 2.0, 3.0, 4.0])]


def _fbits(value: float) -> int:
    return struct.unpack("<I", struct.pack("<f", value))[0]


def make_args(i: int) -> List[ArgSpec]:
    slot, velocity = CASES[i % len(CASES)]
    return [
        ArgSpec(kind="u64", bits=slot),
        ArgSpec(
            kind="ptr",
            mem=b"".join(struct.pack("<I", _fbits(v)) for v in velocity),
            arena_offset=0x7000,
        ),
        ArgSpec(kind="u64", bits=STATE_BASE),
    ]
